```c
#include <stdio.h>

int main() {
    int T;
    scanf("%d", &T);

    while (T--) {
        int N, X;
        scanf("%d %d", &N, &X);

        // The minimum number of rated players with rated opponents
        // is the maximum of 0 and (X - (2 * N - X))
        int min_rated_opponents = (X > 2 * N - X) ? X - (2 * N - X) : 0;

        printf("%d\n", min_rated_opponents);
    }

    return 0;
}
```

