import numpy as np

class Model:
    def __init__(self):
        self.weights = None

    def fit(self, X, y):
        raise NotImplementedError("Subclasses must implement this method")

    def predict(self, X):
        raise NotImplementedError("Subclasses must implement this method")

class LinearModel(Model):
    def fit(self, X, y):
        # Simple linear regression using least squares
        self.weights = np.linalg.inv(X.T @ X) @ X.T @ y

    def predict(self, X):
        return X @ self.weights

class RandomModel(Model):
    def predict(self, X):
        return np.random.rand(len(X))

class DecisionTreeModel(Model):
    def fit(self, X, y):
        # Placeholder for decision tree fitting logic
        pass

    def predict(self, X):
        # Placeholder for decision tree prediction logic
        return np.random.rand(len(X))

class ContextualMultiArmedBandit:
    def __init__(self, context_dim, num_arms=3, models=None):
        if models is None:
            models = [LinearModel(), RandomModel(), DecisionTreeModel()]

        self.context_dim = context_dim
        self.num_arms = num_arms
        self.models = models
        self.rewards = {i: [] for i in range(num_arms)}

    def select_arm(self, context):
        arm_rewards = []
        for model in self.models:
            reward = model.predict(context)
            arm_rewards.append(reward)

        selected_arm = np.argmax(arm_rewards)
        return selected_arm

    def update(self, arm, reward):
        self.rewards[arm].append(reward)

# Example usage
if __name__ == "__main__":
    context_dim = 2
    num_arms = 3
    bandit = ContextualMultiArmedBandit(context_dim, num_arms)

    contexts = np.random.rand(100, context_dim)
    true_rewards = np.random.rand(100, num_arms)

    for t in range(100):
        context = contexts[t]
        arm = bandit.select_arm(context)
        reward = true_rewards[t, arm]
        bandit.update(arm, reward)
```

### Explanation:

1. **Model Class**: This is the base class for all models. It has methods `fit` and `predict`, which need to be implemented by subclasses.
   - `LinearModel`: Implements simple linear regression.
   - `RandomModel`: Predicts random rewards.
   - `DecisionTreeModel`: Placeholder for a decision tree model.

2. **ContextualMultiArmedBandit Class**:
   - Initializes with a given context dimension, number of arms, and list of models.
   - `select_arm`: Selects the best arm based on predictions from each model.
