        self.pending_transactions = []
        self.nodes = {}

    def create_genesis_block(self):
        return Block(0, "0", datetime.now(), [], 1)

    def get_latest_block(self):
        return self.chain[-1]

    def add_transaction(self, sender, recipient, amount, data_size, lifetime_blocks):
        transaction = {
            'sender': sender,
            'recipient': recipient,
            'amount': amount,
            'data_size': data_size,
            'lifetime_blocks': lifetime_blocks,
            'timestamp': datetime.now()
        }
        self.pending_transactions.append(transaction)

    def mine_pending_transactions(self, miner_address):
        if len(self.pending_transactions) == 0:
            return False

        last_block = self.get_latest_block()
        new_block = Block(
            index=last_block.index + 1,
            previous_hash=last_block.hash,
            timestamp=datetime.now(),
            data=self.pending_transactions,
            proof=self.proof_of_work(last_block)
        )
        self.chain.append(new_block)
        self.pending_transactions = []

        # Distribute rewards among nodes hosting the data
        total_data_size = sum([tx['data_size'] for tx in new_block.data])
        reward_per_byte = new_block.data[0]['amount'] / total_data_size
        for tx in new_block.data:
            for node in self.nodes.values():
                if node.address in tx['recipient']:
                    node.balance += reward_per_byte * tx['data_size']

        return True

    def proof_of_work(self, last_block):
        last_proof = last_block.proof
        last_hash = last_block.hash
        proof = 0
        while not self.valid_proof(last_proof, proof, last_hash):
            proof += 1
        return proof

    @staticmethod
    def valid_proof(last_proof, proof, last_hash):
        guess = f'{last_proof}{proof}{last_hash}'.encode()
        guess_hash = hashlib.sha256(guess).hexdigest()
        return guess_hash[:4] == "0000"

