```gdscript
extends Spatial

var chunk_size = 16 # Size of one side of a chunk
var world_size = Vector3(8, 8, 8) # Number of chunks along x, y, z axes
var voxel_data: ArrayArrayArray[int] = []

func _ready():
    initialize_world()

func initialize_world():
    for i in range(world_size.x):
        for j in range(world_size.y):
            for k in range(world_size.z):
                voxel_data.append([i, j, k], 0)

# Function to set a voxel at position (x, y, z)
func set_voxel(x: int, y: int, z: int, value: int):
    if x >= 0 and x < world_size.x * chunk_size and \
       y >= 0 and y < world_size.y * chunk_size and \
       z >= 0 and z < world_size.z * chunk_size:
        voxel_data[x % chunk_size][y % chunk_size][z % chunk_size] = value

# Function to get a voxel at position (x, y, z)
func get_voxel(x: int, y: int, z: int) -> int:
    return voxel_data[x % chunk_size][y % chunk_size][z % chunk_size]
```

### Step 3: Render Voxels

To render the voxels, we need to create cube meshes dynamically. Here’s how you might do this:

```gdscript
func _process(delta):
    update_render()

func update_render():
    var visible_chunks = get_visible_chunks()
    for chunk_pos in visible_chunks:
        draw_chunk(chunk_pos)

func get_visible_chunks() -> Array[Vector3]:
    var visible_chunks = []
    var camera_position = global_transform.origin
    var half_chunk_size = chunk_size / 2

    for i in range(-half_chunk_size, half_chunk_size + 1):
        for j in range(-half_chunk_size, half_chunk_size + 1):
            for k in range(-half_chunk_size, half_chunk_size + 1):
                var pos = Vector3(i, j, k)
                if abs(camera_position.x - pos.x) <= half_chunk_size and \
                   abs(camera_position.y - pos.y) <= half_chunk_size and \
                   abs(camera_position.z - pos.z) <= half_chunk_size:
                    visible_chunks.append(pos)

    return visible_chunks

func draw_chunk(position: Vector3):
    for x in range(chunk_size):
        for y in range(chunk_size):
            for z in range(chunk_size):
                var voxel_value = get_voxel(position.x * chunk_size + x,
                                           position.y * chunk_size + y,
                                           position.z * chunk_size + z)

                if voxel_value != 0:
                    var mesh_instance = MeshInstance.new()
                    mesh_instance.mesh = CubeMesh.new()
                    mesh_instance.transform.basis = Basis(Vector3.ONE)
                    mesh_instance.transform.origin = Vector3(x + position.x * chunk_size,
                                                            y + position.y * chunk_size,
                                                            z + position.z * chunk_size)
                    add_child(mesh_instance)
