#include <jni.h>
#include <stdlib.h>

JNIEXPORT jbyteArray JNICALL Java_ReverbJNI_applyReverb(JNIEnv *env, jobject obj, jbyteArray audioData, jint sampleRate) {
    // Get the length of the input array
    jsize len = (*env)->GetArrayLength(env, audioData);

    // Convert the input array to a C-style array
    jbyte* data = (*env)->GetByteArrayElements(env, audioData, NULL);

    // Allocate memory for the output array
    jbyte* result = (jbyte*) malloc(len * sizeof(jbyte));

    // Apply the reverb effect (simple convolution)
    float impulseResponse[100] = { /* Your impulse response here */ };
    float reverbFactor = 0.5f; // Adjust as needed

    for (int i = 0; i < len; ++i) {
        float sum = 0;
        for (int j = 0; j < 100 && i - j >= 0; ++j) {
            sum += data[i - j] * impulseResponse[j];
        }
        result[i] = (jbyte)(data[i] + reverbFactor * sum);
    }

    // Release the input array elements
    (*env)->ReleaseByteArrayElements(env, audioData, data, 0);

    // Create a new Java byte array for the result
    jbyteArray resultArray = (*env)->NewByteArray(env, len);
    (*env)->SetByteArrayRegion(env, resultArray, 0, len, result);

    // Free the allocated memory
    free(result);

    return resultArray;
}
