               .setSession("MyVPN")
               .addAddress("10.0.2.15", 24) // Local IP address and subnet mask
               .addRoute("0.0.0.0", 0)      // Route all traffic through this VPN
               .setMtu(1500)                // Maximum Transmission Unit (MTU)
               .establish()

           vpnInterface = builder?.let { it.fd }

           return START_STICKY
       }

       override fun onDestroy() {
           super.onDestroy()
           vpnInterface?.close()
       }

       override fun onRevoke() {
           super.onRevoke()
           stopSelf()
       }

       override fun onReceiveAdmissionControlResponse(responseCode: Int) {
           super.onReceiveAdmissionControlResponse(responseCode)
           if (responseCode == VpnService.RESPONSE_CODE_OK) {
               // Start reading from the input stream and writing to the output stream
               Thread {
                   readAndFilterPackets()
               }.start()
           } else {
               stopSelf()
           }
       }

       private fun readAndFilterPackets() {
           try {
               val inputStream = FileInputStream(vpnInterface!!.fileDescriptor)
               val outputStream = FileOutputStream(vpnInterface!!.fileDescriptor)

               while (true) {
                   val buffer = ByteArray(8192)
                   val bytesRead = inputStream.read(buffer)

                   if (bytesRead > 0) {
                       // Filter packets here based on destination IP address
                       filterPackets(buffer, bytesRead)
                       outputStream.write(buffer, 0, bytesRead)
                   }
               }
           } catch (e: Exception) {
               e.printStackTrace()
           }
       }

       private fun filterPackets(data: ByteArray, length: Int) {
           // Implement your packet filtering logic here
           // For example, check the destination IP address and decide whether to allow or drop the packet
           // You may need to parse the IP header to extract the destination IP address
       }
   }
