    const device float* __global inputBuffer,
    const device float* __global outputBuffer,
    uint2 gid [[thread_position_in_grid]],
    constant ImageData& imageData [[buffer(0)]],
    constant int& width [[buffer(1)]],
    constant int& height [[buffer(2)]]
) {
    // Calculate the position in the image
    int x = gid.x;
    int y = gid.y;

    // Initialize sum variables
    float rSum = 0.0f;
    float gSum = 0.0f;
    float bSum = 0.0f;
    float alphaSum = 0.0f;

    // Apply the Gaussian kernel
    for (int ky = -KERNEL_SIZE / 2; ky <= KERNEL_SIZE / 2; ++ky) {
        for (int kx = -KERNEL_SIZE / 2; kx <= KERNEL_SIZE / 2; ++kx) {
            int nx = x + kx;
            int ny = y + ky;

            if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
                float4 pixel = imageData.inputImage.read(int2(nx, ny));
                int index = (ny * width + nx) * 4;
