        }
    }

    // Write the blurred pixel back to the output buffer
    int outIndex = (y * width + x) * 4;
    outputBuffer[outIndex] = rSum;
    outputBuffer[outIndex + 1] = gSum;
    outputBuffer[outIndex + 2] = bSum;
    outputBuffer[outIndex + 3] = alphaSum;
}
