        { "type": "email", "value": "john@example.com" },
        { "type": "phone", "value": "+1-555-1234" }
    ]
};

const entityKeyToSearch = "value";
const result = findEntityInJson(jsonData, entityKeyToSearch);
console.log(result);
```

