                   <a className="block py-2 px-4 text-gray-800 hover:bg-gray-200">About</a>
                 </Link>
               </li>
               {/* Add more links as needed */}
             </ul>
           </nav>
         </aside>

         {/* Main Content */}
         <main className="flex-1 p-4 overflow-auto">
           <button
             className="md:hidden fixed top-4 left-4 z-50 p-2 bg-blue-500 text-white rounded"
             onClick={() => setIsOpen(!isOpen)}
           >
             Menu
           </button>
           {children}
         </main>
       </div>
     );
   };

   export default Layout;
   ```

5. **Modify `_app.js` to use the Layout component**:
   Open `_app.js` and wrap your application with the `Layout` component.
   ```jsx
   import '../styles/globals.css';
   import Layout from '../components/Layout';

   function MyApp({ Component, pageProps }) {
     return (
       <Layout>
         <Component {...pageProps} />
       </Layout>
     );
   }

   export default MyApp;
   ```

This setup will ensure that the sidebar is hidden on mobile devices but becomes visible when the hamburger menu button is clicked. On desktop devices, the sidebar will be permanently displayed without any interaction required. The sliding animation effect is achieved through Tailwind's utility classes for transitions and transforms.

