PLAYER1 = 1
PLAYER2 = 2
ROWS = 6
COLS = 7

def create_board():
    return np.zeros((ROWS, COLS), dtype=int)

def drop_piece(board, row, col, piece):
    board[row][col] = piece

def is_valid_location(board, col):
    return board[ROWS - 1][col] == EMPTY

def get_next_open_row(board, col):
    for r in range(ROWS):
        if board[r][col] == EMPTY:
            return r

def print_board(board):
    print(np.flip(board, 0))

def winning_move(board, piece):
    # Check horizontal locations for win
    for c in range(COLS - 3):
        for r in range(ROWS):
            if all(board[r][c+i] == piece for i in range(4)):
                return True

    # Check vertical locations for win
    for c in range(COLS):
        for r in range(ROWS - 3):
            if all(board[r+i][c] == piece for i in range(4)):
                return True

    # Check positively sloped diagonals
    for c in range(COLS - 3):
        for r in range(ROWS - 3):
            if all(board[r+i][c+i] == piece for i in range(4)):
                return True

    # Check negatively sloped diagonals
    for c in range(COLS - 3):
        for r in range(3, ROWS):
            if all(board[r-i][c+i] == piece for i in range(4)):
                return True

    return False

def main():
    board = create_board()
    turn = PLAYER1

    while True:
        print_board(board)

        if turn == PLAYER1:
            col = int(input("Player 1, make your selection (0-6): "))
        else:
            col = int(input("Player 2, make your selection (0-6): "))

        if not is_valid_location(board, col):
            print("Invalid location, try again.")
            continue

        row = get_next_open_row(board, col)
        drop_piece(board, row, col, turn)

        if winning_move(board, turn):
            print_board(board)
            print(f"Player {turn} wins!")
            break

        turn = PLAYER2 if turn == PLAYER1 else PLAYER1

if __name__ == "__main__":
    main()
```

This code defines a basic Connect-4 game where two players take turns dropping their pieces into columns on a grid. The game checks for a winner after each move by looking for four consecutive pieces horizontally, vertically, or diagonally.

To run this script, you need to have Python installed along with the NumPy library (`pip install numpy`). Enjoy playing Connect-4!

